# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Triton implementation of aten::_foreach_add_ (ScalarList / Scalar forms).

In-place:  self[i] <- self[i] + scalars[i]   (storage of self[i] preserved)

Design:
  * the whole list is packed into as few kernel launches as possible: up to
    _G_MAX contiguous, same-dtype, non-aliasing tensors share ONE launch whose
    flat tile space is the concatenation of their per-tensor tile ranges
    (cumulative bounds decide which tensor a program works on),
  * non-contiguous tensors get their own strided launch (dims sorted by
    ascending |stride| so the fastest-varying lane dimension has the smallest
    stride, int64 offsets),
  * persistent loop over tiles striding by tl.num_programs(0), grid capped by a
    runtime vector-core query (never a hard-coded core count),
  * contiguous tiles move ~32 KB per loop iteration regardless of element
    width (_block_for picks the element count from the dtype itemsize),
  * fp16/bf16 are added in fp32 (ATen opmath) and rounded once on store; when
    the scalar is exactly representable in the storage dtype the single-pass
    native-width add is used instead, which is bit-identical there,
  * zero-numel tensors are skipped entirely (no launch),
  * tensors that share storage are never fused with each other, so the
    sequential list order of ATen in-place foreach semantics is preserved.
"""

import torch
import triton
import triton.language as tl

_MAX_RANK = 8
_BLOCK_BYTES = 32768
_BLOCK_MIN = 1024
_BLOCK_MAX = 16384
_WAVES = 64
_G_MAX = 4

# device -> vector core count (output independent runtime query, cached)
_CORE_CACHE = {}
# (dtype, scalar) -> scalar exactly representable in that dtype
_SCALAR_EXACT = {}


def _device_index():
    try:
        from triton.runtime import driver

        getter = getattr(driver.active, "get_current_device", None)
        if getter is not None:
            return int(getter())
    except Exception:
        pass
    try:
        return int(torch.npu.current_device())
    except Exception:
        return 0


def _num_cores():
    # Fast path: a previously resolved value is reused.
    if _CORE_CACHE:
        for v in _CORE_CACHE.values():
            return v
    idx = _device_index()
    n = 0
    try:
        from triton.runtime import driver

        props = driver.active.utils.get_device_properties(idx)
        n = int(props.get("num_vectorcore", 0) or 0)
        if n <= 0:
            n = int(props.get("num_aicore", 0) or 0)
    except Exception:
        n = 0
    if n <= 0:
        n = 1
    _CORE_CACHE[idx] = n
    return n


def _grid(total_tiles):
    cap = _WAVES * _num_cores()
    return (total_tiles if total_tiles < cap else cap,)


def _block_for(dtype, max_numel=None):
    """Elements per tile so that each loop iteration moves ~_BLOCK_BYTES.

    When the whole workload is smaller than one tile the tile is shrunk to the
    next power of two of the workload, so a small list runs several tiles over
    several programs with small buffers instead of one masked tile on a single
    program."""
    itemsize = getattr(dtype, "itemsize", 4) or 4
    block = _BLOCK_BYTES // itemsize
    if block > _BLOCK_MAX:
        block = _BLOCK_MAX
    if max_numel is not None and max_numel < block:
        p = _BLOCK_MIN
        while p < max_numel and p < block:
            p <<= 1
        block = p
    if block < _BLOCK_MIN:
        block = _BLOCK_MIN
    return block


def _is_exact_scalar(dtype, s):
    """True when s is exactly representable in dtype.

    For fp16/bf16 that makes a native-width add bit-identical to ATen's fp32
    opmath (the fp16/bf16 -> fp32 -> storage double rounding is innocuous), so
    the single vector pass can be used without changing any result."""
    key = (dtype, s)
    hit = _SCALAR_EXACT.get(key)
    if hit is None:
        try:
            hit = float(torch.tensor(s, dtype=dtype).item()) == float(s)
        except Exception:
            hit = False
        if len(_SCALAR_EXACT) > 4096:
            _SCALAR_EXACT.clear()
        _SCALAR_EXACT[key] = hit
    return hit


def _native_ok(dtype, s):
    return dtype in (torch.float16, torch.bfloat16) and _is_exact_scalar(dtype, s)


@triton.jit
def _contig_tile(
    ptr,
    s,
    n,
    t,
    lo,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
    IS_F64: tl.constexpr,
    IS_INT: tl.constexpr,
    NATIVE: tl.constexpr,
):
    offs = (t - lo) * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        x = tl.load(ptr + offs)
    else:
        mask = offs < n
        x = tl.load(ptr + offs, mask=mask, other=0)
    if IS_INT:
        y = x + s
    elif IS_F64:
        y = x + s.to(tl.float64)
    elif NATIVE:
        y = x + s.to(x.dtype)
    else:
        y = x.to(tl.float32) + s
    if EVEN:
        tl.store(ptr + offs, y)
    else:
        tl.store(ptr + offs, y, mask=mask)


@triton.jit
def _fused_contig_add(
    p0,
    p1,
    p2,
    p3,
    s0,
    s1,
    s2,
    s3,
    n0,
    n1,
    n2,
    n3,
    e0,
    e1,
    e2,
    e3,
    G: tl.constexpr,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
    IS_F64: tl.constexpr,
    IS_INT: tl.constexpr,
    NATIVE: tl.constexpr,
):
    ptrs = (p0, p1, p2, p3)
    scals = (s0, s1, s2, s3)
    ns = (n0, n1, n2, n3)
    los = (0, e0, e1, e2)
    his = (e0, e1, e2, e3)
    pid = tl.program_id(0)
    step = tl.num_programs(0)
    total = his[G - 1]
    for t in tl.range(pid, total, step):
        for g in tl.static_range(G):
            if (t >= los[g]) & (t < his[g]):
                _contig_tile(
                    ptrs[g],
                    scals[g],
                    ns[g],
                    t,
                    los[g],
                    BLOCK=BLOCK,
                    EVEN=EVEN,
                    IS_F64=IS_F64,
                    IS_INT=IS_INT,
                    NATIVE=NATIVE,
                )


@triton.jit
def _strided_add_kernel(
    x_ptr,
    s,
    n,
    sh0,
    sh1,
    sh2,
    sh3,
    sh4,
    sh5,
    sh6,
    sh7,
    sd0,
    sd1,
    sd2,
    sd3,
    sd4,
    sd5,
    sd6,
    sd7,
    BLOCK: tl.constexpr,
    RANK: tl.constexpr,
    IS_F64: tl.constexpr,
    IS_INT: tl.constexpr,
    NATIVE: tl.constexpr,
):
    shapes = (sh0, sh1, sh2, sh3, sh4, sh5, sh6, sh7)
    strides = (sd0, sd1, sd2, sd3, sd4, sd5, sd6, sd7)
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    for start in tl.range(pid * BLOCK, n, step):
        idx = start + tl.arange(0, BLOCK)
        mask = idx < n
        rem = idx
        off = tl.zeros((BLOCK,), dtype=tl.int64)
        for k in tl.static_range(RANK):
            sz = shapes[k]
            st = strides[k]
            i = rem % sz
            rem = rem // sz
            off += i.to(tl.int64) * st
        x = tl.load(x_ptr + off, mask=mask, other=0)
        if IS_INT:
            y = x + s
        elif IS_F64:
            y = x + s.to(tl.float64)
        elif NATIVE:
            y = x + s.to(x.dtype)
        else:
            y = x.to(tl.float32) + s
        tl.store(x_ptr + off, y, mask=mask)


_KCACHE = {}


def _spec_key(params, tensors, args_int, scalars):
    """Specialisation key mirroring what the Triton JIT would distinguish:
    constexprs, tensor dtypes, per-int-arg equal-to-one / divisibility-by-16
    and per-pointer 16-byte alignment."""
    ints = 0
    for v in args_int:
        ints = (ints << 2) | (1 if v == 1 else 0) | (2 if (v and v % 16 == 0) else 0)
    align = 0
    for t in tensors:
        align = (align << 1) | (1 if (t.data_ptr() % 16 == 0) else 0)
    stypes = 0
    for s in scalars:
        stypes = (
            (stypes << 2)
            | (1 if isinstance(s, int) else 0)
            | (2 if isinstance(s, float) else 0)
        )
    dts = tuple(t.dtype for t in tensors)
    return params + (dts, ints, align, stypes)


def _fused_launch(args, constexprs, grid, key):
    """Launch the fused kernel, bypassing the JIT dispatch once the exact
    specialisation has been compiled (same launch form, fewer host ops)."""
    ck = _KCACHE.get(key, 0)
    if ck:
        try:
            ck[grid](*args)
            return
        except Exception:
            _KCACHE[key] = None
    _fused_contig_add[grid](*args, **constexprs)
    if ck == 0:
        try:
            compiled = _fused_contig_add.foreach_add_scalar_list_(
                *args, grid=grid, warmup=True, **constexprs
            )
            _KCACHE[key] = compiled if hasattr(compiled, "__getitem__") else None
        except Exception:
            _KCACHE[key] = None


def _launch_group(items, native):
    """One launch for up to _G_MAX contiguous, same-dtype, disjoint tensors."""
    g = len(items)
    first = items[0][0]
    dt = first.dtype
    is_int = not dt.is_floating_point
    is_f64 = dt == torch.float64
    BLOCK = _block_for(dt, max(t.numel() for t, _ in items))
    ends = []
    cum = 0
    even = True
    for t, _ in items:
        n = t.numel()
        cum += (n + BLOCK - 1) // BLOCK
        ends.append(cum)
        if n % BLOCK != 0:
            even = False
    pad = _G_MAX - g
    ptrs = [t for t, _ in items] + [first] * pad
    scals = [s for _, s in items]
    scals = scals + [scals[0] * 0] * pad
    ns = [t.numel() for t, _ in items] + [0] * pad
    ends = ends + [cum] * pad
    args = (
        ptrs[0],
        ptrs[1],
        ptrs[2],
        ptrs[3],
        scals[0],
        scals[1],
        scals[2],
        scals[3],
        ns[0],
        ns[1],
        ns[2],
        ns[3],
        ends[0],
        ends[1],
        ends[2],
        ends[3],
    )
    constexprs = dict(
        G=g, BLOCK=BLOCK, EVEN=even, IS_F64=is_f64, IS_INT=is_int, NATIVE=native
    )
    key = _spec_key(
        (g, BLOCK, even, is_f64, is_int, native),
        ptrs,
        (ns[0], ns[1], ns[2], ns[3], ends[0], ends[1], ends[2], ends[3]),
        scals,
    )
    _fused_launch(args, constexprs, _grid(cum), key)


def _launch_strided(t, s, native):
    """In-place self += s for one non-contiguous tensor."""
    n = t.numel()
    dt = t.dtype
    is_int = not dt.is_floating_point
    is_f64 = dt == torch.float64
    BLOCK = _block_for(dt, n)
    pairs = sorted(
        ((abs(st), sz, st) for sz, st in zip(t.shape, t.stride()) if sz > 1),
        key=lambda p: p[0],
    )
    rank = len(pairs)
    if rank > _MAX_RANK:
        raise RuntimeError("foreach_add_: rank too large for the strided kernel")
    shapes = [1] * _MAX_RANK
    strides = [0] * _MAX_RANK
    for k, (_, sz, st) in enumerate(pairs):
        shapes[k] = int(sz)
        strides[k] = int(st)
    tiles = (n + BLOCK - 1) // BLOCK
    _strided_add_kernel[_grid(tiles)](
        t,
        s,
        n,
        shapes[0],
        shapes[1],
        shapes[2],
        shapes[3],
        shapes[4],
        shapes[5],
        shapes[6],
        shapes[7],
        strides[0],
        strides[1],
        strides[2],
        strides[3],
        strides[4],
        strides[5],
        strides[6],
        strides[7],
        BLOCK=BLOCK,
        RANK=rank,
        IS_F64=is_f64,
        IS_INT=is_int,
        NATIVE=native,
    )


def _run_pairs(pairs):
    """Apply self[i] += s[i] in list order, fusing contiguous runs."""
    group = []
    group_storages = []
    group_native = False
    for t, s in pairs:
        if t.numel() == 0:
            continue
        native = _native_ok(t.dtype, s)
        if not t.is_contiguous():
            if group:
                _launch_group(group, group_native)
                group = []
                group_storages = []
            _launch_strided(t, s, native)
            continue
        storage = t.untyped_storage().data_ptr()
        if group and (
            len(group) >= _G_MAX
            or storage in group_storages
            or group[0][0].dtype != t.dtype
            or native != group_native
        ):
            _launch_group(group, group_native)
            group = []
            group_storages = []
        group.append((t, s))
        group_storages.append(storage)
        group_native = native
    if group:
        _launch_group(group, group_native)


def foreach_add_scalar_list_(self, scalars, alpha=1):
    """In-place foreach add; mutates every tensor in ``self`` and returns None."""
    tensors = self
    if isinstance(tensors, torch.Tensor):
        tensors = [tensors]
    elif not isinstance(tensors, (list, tuple)):
        tensors = list(tensors)
    if len(tensors) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")

    if isinstance(scalars, torch.Tensor):
        if scalars.numel() == 1:
            # 0-dim / single element tensor scalar, broadcast over the list.
            v = scalars.item()
            _run_pairs([(t, v) for t in tensors])
            return None
        scalars = list(scalars)
    elif isinstance(scalars, (int, float, bool)):
        # Scalar overload: one value broadcast over the whole list.
        _run_pairs([(t, scalars) for t in tensors])
        return None
    elif not isinstance(scalars, (list, tuple)):
        scalars = list(scalars)

    if len(scalars) != len(tensors):
        raise RuntimeError(
            "Tensor list must have same number of elements as scalar list."
        )

    pairs = []
    for t, s in zip(tensors, scalars):
        if isinstance(s, torch.Tensor):
            if s.numel() != 1:
                raise RuntimeError(
                    "foreach_add_: only 0-dim tensor scalars are supported"
                )
            s = s.item()
        elif not isinstance(s, (int, float, bool)):
            raise TypeError("foreach_add_: scalars must be numbers or 0-dim tensors")
        pairs.append((t, s))
    _run_pairs(pairs)
    return None
